args.command:
cd /tmp/probe && export HOME=/tmp/probe/home2 && echo "=== no args, stdin /dev/null, -n ==="; /workspace/executable -n < /dev/null > na.out 2>na.err; echo EXIT:$?; echo out:; cat na.out; echo err:; cat na.err
echo "=== -N no args ==="; /workspace/executable -n -N < /dev/null > nn.out 2>nn.err; echo EXIT:$?; cat nn.out; cat nn.err
echo "=== -r with plain file ==="; /workspace/executable -n -r app.log 2>&1 | head -2; echo EXIT:${PIPESTATUS[0]}
echo "=== -- separator ==="; /workspace/executable -n -- app.log 2>&1 | head -2; echo EXIT:${PIPESTATUS[0]}
